import {
  StyledRelatedAnalysisActions,
  StyledRelatedAnalysisCard,
  StyledRelatedAnalysisContent,
  StyledRelatedAnalysisCta,
  StyledRelatedAnalysisDescription,
  StyledRelatedAnalysisLabel,
  StyledRelatedAnalysisTitle,
  StyledRelatedAnalysisWarning,
} from './RelatedAnalysisCard.styles';

export interface RelatedAnalysisCardProps {
  title: string;
  description: string;
  buttonLabel: string;
  onNavigate: () => void;
  warning?: string;
  dataTestId?: string;
}

export const RelatedAnalysisCard = ({
  title,
  description,
  buttonLabel,
  onNavigate,
  warning,
  dataTestId,
}: RelatedAnalysisCardProps) => {
  return (
    <StyledRelatedAnalysisCard data-testid={dataTestId}>
      <StyledRelatedAnalysisContent>
        <StyledRelatedAnalysisLabel
          data-testid={dataTestId ? `${dataTestId}-label` : undefined}
        >
          Related Analysis
        </StyledRelatedAnalysisLabel>

        <StyledRelatedAnalysisTitle
          data-testid={dataTestId ? `${dataTestId}-title` : undefined}
        >
          {title}
        </StyledRelatedAnalysisTitle>

        <StyledRelatedAnalysisDescription
          data-testid={dataTestId ? `${dataTestId}-description` : undefined}
        >
          {description}
        </StyledRelatedAnalysisDescription>
      </StyledRelatedAnalysisContent>

      <StyledRelatedAnalysisActions>
        <StyledRelatedAnalysisCta
          type="button"
          onClick={onNavigate}
          data-testid={dataTestId ? `${dataTestId}-button` : undefined}
        >
          {buttonLabel}
        </StyledRelatedAnalysisCta>

        {warning && (
          <StyledRelatedAnalysisWarning
            data-testid={dataTestId ? `${dataTestId}-warning` : undefined}
          >
            {warning}
          </StyledRelatedAnalysisWarning>
        )}
      </StyledRelatedAnalysisActions>
    </StyledRelatedAnalysisCard>
  );
};
